<?php get_header(); while(have_posts()):the_post(); $id=get_the_ID(); $cities=wp_get_post_terms($id,'bsktv_city',array('fields'=>'names')); $types=wp_get_post_terms($id,'bsktv_type',array('fields'=>'names')); ?>
<main class="single-page"><article>
<header class="store-hero-detail"><div class="store-hero-image"><?php if(has_post_thumbnail())the_post_thumbnail('full',array('fetchpriority'=>'high'));else echo '<div class="store-card-placeholder">BSKTV</div>'; ?><div class="store-hero-overlay"></div></div><div class="container store-hero-content"><div class="breadcrumbs"><a href="<?php echo esc_url(home_url('/')); ?>">首頁</a><span>/</span><?php echo esc_html(implode('、',$cities)); ?></div><div class="store-kicker"><?php echo esc_html(implode(' · ',$types)); ?></div><h1><?php the_title(); ?></h1><?php if($p=bsktv_meta('bsktv_price'))echo '<div class="hero-price">'.esc_html($p).'</div>'; ?><div class="hero-actions"><button class="btn btn-gold" type="button" data-favorite data-id="<?php echo esc_attr($id); ?>">♡ 收藏店家</button><?php if($map=bsktv_meta('bsktv_map'))echo '<a class="btn btn-light" target="_blank" rel="noopener noreferrer" href="'.esc_url($map).'">查看地圖</a>'; ?></div></div></header>
<div class="container section"><div class="single-layout"><div class="article-main"><div class="article-meta"><span>更新於 <?php echo esc_html(get_the_modified_date()); ?></span><span><?php echo esc_html(bsktv_views($id)); ?> 次瀏覽</span></div><div class="article-content"><?php the_content(); ?></div></div><aside class="store-info"><div class="info-sticky"><div class="info-title"><span class="eyebrow">STORE INFO</span><h2>店家資訊</h2></div><?php $fields=array('bsktv_address'=>'地址','bsktv_hours'=>'營業時間','bsktv_phone'=>'電話','bsktv_line'=>'LINE／聯絡方式','bsktv_model'=>'消費模式','bsktv_room'=>'包廂資訊');foreach($fields as $k=>$label){$v=bsktv_meta($k);if($v)echo '<div class="info-row"><span class="info-label">'.esc_html($label).'</span><span>'.esc_html($v).'</span></div>';}if($phone=bsktv_meta('bsktv_phone'))echo '<a class="btn btn-primary btn-full" href="tel:'.esc_attr(preg_replace('/[^0-9+]/','',$phone)).'">電話聯絡</a>';if($line=bsktv_meta('bsktv_line'))echo '<div class="contact-line">'.esc_html($line).'</div>';if($website=bsktv_meta('bsktv_website'))echo '<a class="text-link" target="_blank" rel="noopener noreferrer" href="'.esc_url($website).'">官方網站 →</a>'; ?></div></aside></div></div></article><?php get_template_part('template-parts/related'); ?></main><?php endwhile; get_footer(); ?>
